#!/usr/bin/env bash
set -e

GIT_ROOT=$(git rev-parse --show-toplevel)
cd "$GIT_ROOT"

# Usage: test_lint_doc.sh [file.md...], every tracked .md when omitted.
# .agents/skills/api-* is generated by openapi2skill, so it is not linted.
if [ $# -gt 0 ]; then
    MARKDOWN_FILES=("$@")
else
    mapfile -t MARKDOWN_FILES < <(git ls-files "*.md" ":!.agents/skills/api-*")
fi

markdownlint -c "$GIT_ROOT/.markdownlint.json" "${MARKDOWN_FILES[@]}"

markdown-link-check --config "$GIT_ROOT/.markdown-link-check.json" "${MARKDOWN_FILES[@]}"

# Not mandatory yet and too verbose
# cspell lint "$GIT_ROOT" --gitignore -c "$GIT_ROOT/.cspell.yml"
